"""Identity-initialized attention output gating with full AttnRes-Canon.

A token-dependent gate multiplies the attention output before its output projection.
A direct headwise gate or nonlinear low-rank channelwise gate starts at one.
Full-width depth retrieval and Canon A/B/C/D retain the current-source control.
"""
import torch
from torch import nn
from torch.nn import functional as F
from nanochat.flash_attention import flash_attn
from nexttransformer.models.backbone import CausalSelfAttention, Linear, apply_rotary_emb, norm
from nexttransformer.models.lm import ReferenceLM


class Canon(nn.Module):
    def __init__(self, width, size, dilation=1):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(width, 1, size))
        self.size, self.dilation = size, dilation

    def forward(self, x):
        y = F.conv1d(F.pad(x.transpose(1, 2), ((self.size - 1) * self.dilation, 0)),
                     self.weight.to(x.dtype), dilation=self.dilation, groups=x.shape[-1])
        return x + y.transpose(1, 2)


class OutputGate(nn.Module):
    """Identity-initialized token gate, direct per head or low-rank per channel."""
    def __init__(self, width, heads, rank):
        super().__init__()
        self.down = Linear(width, rank, bias=False) if rank else None
        self.up = Linear(rank if rank else width, width if rank else heads, bias=False)

    def forward(self, x):
        z = F.silu(self.down(x)) if self.down is not None else x
        return 2 * torch.sigmoid(self.up(z))


class BraidedAttention(CausalSelfAttention):
    def __init__(self, config, layer):
        super().__init__(config, layer)
        self.canon_qkv = nn.ModuleList(Canon(config.width, config.option("kernel_size")) for _ in range(3))
        rank = config.option("output_gate_rank")
        self.gate_channels = self.head_dim if rank else 1
        self.output_gate = OutputGate(config.width, self.n_head, rank)

    def forward(self, x, ve, cos_sin, window_size, kv_cache):
        if kv_cache is not None:
            raise NotImplementedError("full-sequence attention required")
        b, t, c = x.shape
        q, k, v = (conv(y) for conv, y in zip(self.canon_qkv, (self.c_q(x), self.c_k(x), self.c_v(x))))
        q = q.view(b, t, self.n_head, self.head_dim)
        k = k.view(b, t, self.n_kv_head, self.head_dim)
        v = v.view(b, t, self.n_kv_head, self.head_dim)
        if ve is not None:
            v = v + 3 * torch.sigmoid(self.ve_gate(x[..., :self.ve_gate_channels])).unsqueeze(-1) * ve.view_as(v)
        cos, sin = cos_sin
        q, k = apply_rotary_emb(q, cos, sin), apply_rotary_emb(k, cos, sin)
        q, k = norm(q) * 1.2, norm(k) * 1.2
        y = flash_attn.flash_attn_func(q, k, v, causal=True, window_size=window_size)
        y = y * self.output_gate(x).view(b, t, self.n_head, self.gate_channels)
        return self.c_proj(y.contiguous().view(b, t, c))


class BraidedMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.c_fc = Linear(config.width, config.mlp_width, bias=False)
        self.c_proj = Linear(config.mlp_width, config.width, bias=False)
        self.canon = Canon(config.mlp_width, config.option("kernel_size"), config.option("ffn_dilation"))

    def forward(self, x):
        return self.c_proj(F.relu(self.canon(self.c_fc(x))).square())


class ContextQuery(nn.Module):
    def __init__(self, width, rank):
        super().__init__()
        self.down = Linear(width, rank, bias=False)
        self.up = Linear(rank, width, bias=False)

    @torch.no_grad()
    def reset_parameters(self):
        s = 3 ** 0.5 * self.down.in_features ** -0.5
        nn.init.uniform_(self.down.weight, -s, s)
        nn.init.zeros_(self.up.weight)

    def forward(self, x):
        return self.up(F.silu(self.down(norm(x))))


def _embedding_reset_by_shell():
    pass


class BraidedDepthLM(ReferenceLM):
    def __init__(self, config):
        super().__init__(config)
        self.depth_heads = config.option("depth_heads")
        self.depth_dim = config.width // self.depth_heads
        self.group_layers = config.option("group_layers")
        self.context_scale = config.option("context_scale")
        self.depth_queries = nn.Parameter(torch.empty(2 * config.n_layer + 1, config.width))
        self.canon = nn.ModuleList(Canon(config.width, config.option("kernel_size")) for _ in range(2 * config.n_layer))
        rank = config.option("query_rank")
        self.residual_maps = nn.ModuleList(ContextQuery(config.width, rank) for _ in range(2 * config.n_layer + 1)) if rank else nn.ModuleList()
        for module in self.modules():
            if isinstance(module, nn.Embedding):
                module.reset_parameters = _embedding_reset_by_shell

    def _key(self, source):
        return norm(source.unflatten(-1, (self.depth_heads, self.depth_dim)))

    def _depth_read(self, step, sources, keys):
        query = self.depth_queries[step].to(keys[0].dtype).view(self.depth_heads, self.depth_dim)
        if len(self.residual_maps):
            context = self.residual_maps[step](sources[-1]).unflatten(-1, (self.depth_heads, self.depth_dim))
            query = query + self.context_scale * (self.depth_dim ** -0.5) * context
        key_tensor = torch.stack(keys, 0)
        if len(self.residual_maps):
            logits = torch.einsum("sbthd,bthd->sbth", key_tensor, query)
        else:
            logits = torch.einsum("sbthd,hd->sbth", key_tensor, query)
        logits = logits.to(torch.promote_types(logits.dtype, torch.float32))
        weights = logits.softmax(0).to(sources[0].dtype)
        values = torch.stack(sources, 0).unflatten(-1, (self.depth_heads, self.depth_dim))
        result = torch.einsum("sbth,sbthd->bthd", weights, values)
        return result.flatten(-2)

    def _ordinary_hidden(self, idx):
        c = self.config
        x = self._embed_reference(idx)
        sources, keys, partial = [], [], x
        for step in range(2 * c.n_layer):
            key = self._key(partial)
            hidden = self._depth_read(step, sources + [partial], keys + [key])
            self._record("depth_read", sublayer=step, sources=len(sources) + 1, streams=self.depth_heads, tokens=idx.numel())
            if step % 2 == 0 and (step // 2) % self.group_layers == 0:
                sources.append(partial)
                keys.append(key)
                partial = None
            hidden = self.canon[step](hidden)
            output = self._attention_branch(hidden, idx, step // 2) if step % 2 == 0 else self.transformer.h[step // 2].mlp(norm(hidden))
            partial = output if partial is None else partial + output
        hidden = self._depth_read(2 * c.n_layer, sources + [partial], keys + [self._key(partial)])
        self._record("depth_read", sublayer=2 * c.n_layer, sources=len(sources) + 1, streams=self.depth_heads, tokens=idx.numel())
        return hidden, None


model = BraidedDepthLM
frozen = ("resid_lambdas", "x0_lambdas", "backout_lambda")

def mixer(config, layer):
    return BraidedAttention(config, layer)

def ffn(config, layer):
    return BraidedMLP(config)

@torch.no_grad()
def init(model):
    for module in model.modules():
        if isinstance(module, Canon):
            nn.init.zeros_(module.weight)
        if isinstance(module, OutputGate):
            if module.down is not None:
                s = 3 ** 0.5 * module.down.in_features ** -0.5
                nn.init.uniform_(module.down.weight, -s, s)
            nn.init.zeros_(module.up.weight)
        if isinstance(module, ContextQuery):
            s = 3 ** 0.5 * model.config.width ** -0.5
            nn.init.uniform_(module.down.weight, -s, s)
            nn.init.zeros_(module.up.weight)

def check(config):
    heads = config.option("depth_heads")
    if type(heads) is not int or heads < 1 or config.width % heads:
        raise ValueError("depth_heads must divide width")
    for name in ("kernel_size", "ffn_dilation", "group_layers"):
        if type(config.option(name)) is not int or config.option(name) < 1:
            raise ValueError(name + " must be a positive integer")
    if type(config.option("query_rank")) is not int or config.option("query_rank") < 0:
        raise ValueError("query_rank must be a nonnegative integer")
    if not 0 < config.option("context_scale") <= 4:
        raise ValueError("context_scale must be in (0, 4]")

    if type(config.option("output_gate_rank")) is not int or config.option("output_gate_rank") < 0:
        raise ValueError("output_gate_rank must be a nonnegative integer")

