"""Identity-initialized attention output gating with full AttnRes-Canon.

A token-dependent gate multiplies the attention output before its output projection.
A direct headwise gate or nonlinear low-rank channelwise gate starts at one.
Full-width depth retrieval and Canon A/B/C/D retain the current-source control.
"""
import torch
from torch import nn
from torch.nn import functional as F
from nanochat.flash_attention import flash_attn
from nexttransformer.models.backbone import CausalSelfAttention, Linear, apply_rotary_emb, norm
from nexttransformer.models.lm import ReferenceLM


class Canon(nn.Module):
    def __init__(self, width, size, dilation=1):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(width, 1, size))
        self.size, self.dilation = size, dilation

    def forward(self, x):
        y = F.conv1d(F.pad(x.transpose(1, 2), ((self.size - 1) * self.dilation, 0)),
                     self.weight.to(x.dtype), dilation=self.dilation, groups=x.shape[-1])
        return x + y.transpose(1, 2)


class OutputGate(nn.Module):
    """Identity-initialized token gate, direct per head or low-rank per channel."""
    def __init__(self, width, heads, rank):
        super().__init__()
        self.down = Linear(width, rank, bias=False) if rank else None
        self.up = Linear(rank if rank else width, width if rank else heads, bias=False)

    def forward(self, x):
        z = F.silu(self.down(x)) if self.down is not None else x
        return 2 * torch.sigmoid(self.up(z))


class BraidedAttention(CausalSelfAttention):
    def __init__(self, config, layer):
        super().__init__(config, layer)
        self.canon_qkv = nn.ModuleList(Canon(config.width, config.option("kernel_size")) for _ in range(3))
        rank = config.option("output_gate_rank")
        self.gate_channels = self.head_dim if rank else 1
        self.output_gate = OutputGate(config.width, self.n_head, rank)

    def forward(self, x, ve, cos_sin, window_size, kv_cache):
        if kv_cache is not None:
            raise NotImplementedError("full-sequence attention required")
        b, t, c = x.shape
        q, k, v = (conv(y) for conv, y in zip(self.canon_qkv, (self.c_q(x), self.c_k(x), self.c_v(x))))
        q = q.view(b, t, self.n_head, self.head_dim)
        k = k.view(b, t, self.n_kv_head, self.head_dim)
        v = v.view(b, t, self.n_kv_head, self.head_dim)
        if ve is not None:
            v = v + 3 * torch.sigmoid(self.ve_gate(x[..., :self.ve_gate_channels])).unsqueeze(-1) * ve.view_as(v)
        cos, sin = cos_sin
        q, k = apply_rotary_emb(q, cos, sin), apply_rotary_emb(k, cos, sin)
        q, k = norm(q) * 1.2, norm(k) * 1.2
        y = flash_attn.flash_attn_func(q, k, v, causal=True, window_size=window_size)
        y = y * self.output_gate(x).view(b, t, self.n_head, self.gate_channels)
        return self.c_proj(y.contiguous().view(b, t, c))


